export const today=()=>new Date().toLocaleDateString('en-CA');
export const quarter=date=>Math.floor((Number(date.slice(5,7))-1)/3)+1;
export function progress(project,tasks){const list=tasks.filter(t=>t.projectId===project.id);return list.length?Math.round(list.filter(t=>t.status==='Done').length/list.length*100):0}
export function health(project,tasks,asOf=today()){const p=progress(project,tasks);if(p===100)return 'Complete';if(project.due<asOf)return 'Off track';const list=tasks.filter(t=>t.projectId===project.id&&t.status!=='Done');return list.some(t=>t.status==='Blocked'||t.due<asOf)?'At risk':'On track'}
export function scopeProjects(data,year,q,search=''){return data.projects.filter(p=>p.start<=`${year}-12-31`&&p.due>=`${year}-01-01`&&(!q||(p.start<=`${year}-${String(q*3).padStart(2,'0')}-${q===1||q===4?'31':'30'}`&&p.due>=`${year}-${String(q*3-2).padStart(2,'0')}-01`))&&`${p.name} ${p.owner} ${p.description}`.toLowerCase().includes(search.toLowerCase()))}
export function monthlySeries(data,year,ids){return Array.from({length:12},(_,m)=>{const end=`${year}-${String(m+1).padStart(2,'0')}-${new Date(year,m+1,0).getDate()}`;const tasks=data.tasks.filter(t=>ids.includes(t.projectId));return {month:m,planned:tasks.length?Math.round(tasks.filter(t=>t.due<=end).length/tasks.length*100):0,actual:tasks.length?Math.round(tasks.filter(t=>t.status==='Done'&&t.completedAt&&t.completedAt<=end).length/tasks.length*100):0}})}
export function validateData(data){if(!data||data.version!==1||!Array.isArray(data.projects)||!Array.isArray(data.tasks)||!Array.isArray(data.risks)||!Array.isArray(data.milestones)||!Array.isArray(data.activity)||typeof data.workspace!=='string')throw Error('Choose a valid Prosjektledelse backup.');const date=x=>typeof x==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(x)&&!Number.isNaN(Date.parse(x));const text=x=>typeof x==='string';const unique=list=>list.every(x=>x&&text(x.id)&&/^[a-zA-Z0-9_-]{1,100}$/.test(x.id))&&new Set(list.map(x=>x.id)).size===list.length;if(![data.projects,data.tasks,data.risks,data.milestones,data.activity].every(unique))throw Error('Backup contains invalid or duplicate records.');for(const p of data.projects)if(!text(p.name)||!text(p.owner)||!text(p.description)||!['olive','clay','sand','slate'].includes(p.color)||!date(p.start)||!date(p.due)||p.start>p.due||![p.budget,p.spent].every(x=>Number.isFinite(x)&&x>=0))throw Error('Invalid project in backup.');const ids=new Set(data.projects.map(p=>p.id));for(const t of data.tasks)if(!ids.has(t.projectId)||!text(t.name)||!text(t.owner)||!['To do','In progress','Blocked','Done'].includes(t.status)||!['Low','Medium','High'].includes(t.priority)||!date(t.due)||(t.completedAt&&!date(t.completedAt)))throw Error('Invalid task in backup.');for(const m of data.milestones)if(!ids.has(m.projectId)||!text(m.name)||!date(m.due)||typeof m.done!=='boolean')throw Error('Invalid milestone in backup.');for(const r of data.risks)if(!ids.has(r.projectId)||!text(r.name)||!text(r.owner)||!text(r.mitigation)||!['Low','Medium','High'].includes(r.impact)||!['Low','Medium','High'].includes(r.likelihood)||!['Open','Mitigated','Closed'].includes(r.status))throw Error('Invalid risk in backup.');for(const a of data.activity)if(!text(a.text)||!text(a.at)||Number.isNaN(Date.parse(a.at)))throw Error('Invalid activity in backup.');return data}
